const ROOT = '/fixture-plugin'
const COUNTS: Record<Sequence, number> = { ok: 80, work: 48, done: 38, error: 30, update: 36, noConfig: 72, fika: 270 }
function fixture(sequence: Sequence): Fixture {
  return FIXTURES[sequence === 'fika' ? 'large' : sequence === 'work' ? 'alternate' : 'small']!
}
function packetFor(sequence: Sequence, firstFrame: number): Packet {
  const data = fixture(sequence)
  return { format: 'sth-rgba-delta-v1', sequence, width: data.width, height: data.width, firstFrame,
    frames: Array.from({ length: Math.min(6, COUNTS[sequence] - firstFrame) }, (_, index) => {
      const frame = firstFrame + index
      return { frame, kind: frame % 30 === 0 ? 'key' : 'delta',
        data: frame % 30 === 0 ? data.keys[String(frame)]! : data.delta, sha256: data.hashes[frame]! }
    }),
  }
}
function fixtureFiles(packed = true) {
  const reads: string[] = [], markers: string[] = []
  let rewrite: ((packet: Packet) => Packet | string) | undefined
  let waitForRead: (() => Promise<void>) | undefined
  const exists = async (path: string) => { markers.push(path); return packed }
  const readFile = async (path: string) => {
    reads.push(path)
    if (waitForRead) await waitForRead()
    const match = path.match(/\/buddy-codec\/([^/]+)\/(\d+)\.json$/)
    if (!match) throw new Error(`Unexpected fixture path: ${path}`)
    const packet = packetFor(match[1] as Sequence, Number(match[2]))
    const result = rewrite ? rewrite(packet) : packet
    return typeof result === 'string' ? result : JSON.stringify(result)
  }
  return { reads, markers, exists, readFile,
    rewrite: (next: typeof rewrite) => { rewrite = next },
    waitForRead: (next: typeof waitForRead) => { waitForRead = next },
  }
}
async function assertPixels(source: ImageSource, sequence: Sequence, frame: number): Promise<void> {
  if (!('rgba' in source)) throw new Error('Expected the packed RGBA source')
  const expected = fixture(sequence)
  expect(source.width).toBe(expected.width)
  expect(source.height).toBe(expected.width)
  const bytes = fromBase64(source.rgba)
  expect(bytes.length).toBe(expected.width * expected.width * 4)
  const digest = await crypto.subtle.digest('SHA-256', bytes)
  const hex = Array.from(new Uint8Array(digest), value => value.toString(16).padStart(2, '0')).join('')
  expect(hex).toBe(expected.hashes[frame])
}
function readFrame(reader: ReturnType<typeof createBuddyImageReader>, files: ReturnType<typeof fixtureFiles>, sequence: Sequence, frame: number) {
  return reader.read(ROOT, files.exists, files.readFile, sequence, frame)
}

describe('Lossless Buddy frame decoding', () => {
  test('base64 preserves every byte, including zeros and high bits', () => {
    const bytes = Uint8Array.from({ length: 1024 }, (_, index) => index % 256)
    expect(Array.from(fromBase64(toBase64(bytes)))).toEqual(Array.from(bytes))
  })

  test('retains one decoded frame and refuses a delta without its exact predecessor', () => {
    const decoder = makeDecoder(), packet = packetFor('ok', 0)
    expect(() => decoder.decode(packet, packet.frames[1]!)).toThrow('Missing delta predecessor')
    for (const frame of packet.frames) {
      const decoded = decoder.decode(packet, frame)
      expect(decoded.length).toBe(384 * 384 * 4)
      expect(decoder.cachedBytes).toBe(384 * 384 * 4)
    }
    expect(() => decoder.decode(packet, packet.frames[2]!)).toThrow('Missing delta predecessor')
    decoder.reset()
    expect(decoder.cachedBytes).toBe(0)
    expect(() => decoder.decode(packet, packet.frames[1]!)).toThrow('Missing delta predecessor')
  })

  test('checksum failure leaves the previous valid frame available for recovery', async () => {
    const decoder = makeDecoder(), packet = packetFor('ok', 0)
    decoder.decode(packet, packet.frames[0]!)
    const delta = packet.frames[1]!, damaged = fromBase64(delta.data)
    damaged[damaged.length - 1] = damaged[damaged.length - 1]! ^ 1
    expect(() => decoder.decode(packet, { ...delta, data: toBase64(damaged) })).toThrow('Corrupt frame checksum')
    const recovered = decoder.decode(packet, delta)
    await assertPixels({ rgba: toBase64(recovered), width: 384, height: 384 }, 'ok', 1)
    expect(() => decoder.decode({ ...packet, width: 1024, height: 1024 }, packet.frames[0]!)).toThrow('Invalid RGBA dimensions')
    expect(() => decoder.decode(packet, { ...packet.frames[0]!, data: 'eA==' })).toThrow('Invalid compressed frame size')
  })
})

describe('Buddy image reader', () => {
  test('absent bundle marker preserves original PNG paths, frame counts and file-only rendering', async () => {
    const reader = createBuddyImageReader(), files = fixtureFiles(false)
    for (const sequence of ['ok', 'work', 'done', 'error', 'update', 'noConfig', 'fika'] as const) {
      const end = COUNTS[sequence] - 1
      const filename = sequence === 'fika' ? `assets/fika/fika-${String(end + 1).padStart(4, '0')}.png`
        : `assets/frames/${sequence}/${String(end).padStart(3, '0')}.png`
      expect(await readFrame(reader, files, sequence, -1)).toEqual({ file: `${ROOT}/${filename}`, format: 'png' })
      const first = sequence === 'fika' ? 'assets/fika/fika-0001.png' : `assets/frames/${sequence}/000.png`
      expect(await readFrame(reader, files, sequence, COUNTS[sequence])).toEqual({ file: `${ROOT}/${first}`, format: 'png' })
    }
    expect(files.reads).toHaveLength(0)
    expect(files.markers).toEqual([`${ROOT}/assets/buddy-codec/index.json`])
  })

  test('contiguous playback keeps exact pixels across packet boundaries and caches only the last image', async () => {
    const reader = createBuddyImageReader(), files = fixtureFiles()
    const first = await readFrame(reader, files, 'ok', 0)
    expect(await readFrame(reader, files, 'ok', 0)).toBe(first)
    for (let frame = 0; frame < 9; frame++) await assertPixels(await readFrame(reader, files, 'ok', frame), 'ok', frame)
    expect(files.reads).toEqual([`${ROOT}/assets/buddy-codec/ok/0000.json`, `${ROOT}/assets/buddy-codec/ok/0006.json`])
    const revisited = await readFrame(reader, files, 'ok', 0)
    expect(revisited).not.toBe(first)
    await assertPixels(revisited, 'ok', 0)
    expect(files.reads[2]).toBe(`${ROOT}/assets/buddy-codec/ok/0000.json`)
    expect(files.markers).toHaveLength(1)
  })

  test('forward skips begin at the nearest keyframe and backwards seeks reconstruct from that keyframe', async () => {
    const reader = createBuddyImageReader(), files = fixtureFiles()
    await assertPixels(await readFrame(reader, files, 'ok', 2), 'ok', 2)
    await assertPixels(await readFrame(reader, files, 'ok', 35), 'ok', 35)
    expect(files.reads).toEqual([`${ROOT}/assets/buddy-codec/ok/0000.json`, `${ROOT}/assets/buddy-codec/ok/0030.json`])
    await assertPixels(await readFrame(reader, files, 'ok', 31), 'ok', 31)
    expect(files.reads[2]).toBe(`${ROOT}/assets/buddy-codec/ok/0030.json`)
    await assertPixels(await readFrame(reader, files, 'ok', 8), 'ok', 8)
    expect(files.reads.slice(-2)).toEqual([`${ROOT}/assets/buddy-codec/ok/0000.json`, `${ROOT}/assets/buddy-codec/ok/0006.json`])
  })

  test('pose changes, animation wrap and 720px Fika do not reuse another sequence pixels', async () => {
    const reader = createBuddyImageReader(), files = fixtureFiles()
    await assertPixels(await readFrame(reader, files, 'ok', 2), 'ok', 2)
    await assertPixels(await readFrame(reader, files, 'work', 2), 'work', 2)
    await assertPixels(await readFrame(reader, files, 'ok', 79), 'ok', 79)
    await assertPixels(await readFrame(reader, files, 'ok', 80), 'ok', 0)
    await assertPixels(await readFrame(reader, files, 'fika', 31), 'fika', 31)
    await assertPixels(await readFrame(reader, files, 'fika', 270), 'fika', 0)
  })

  test('simultaneous render and animation requests serialize predecessor state', async () => {
    const reader = createBuddyImageReader(), files = fixtureFiles()
    let release!: () => void, started!: () => void
    const gate = new Promise<void>(resolve => { release = resolve })
    const entered = new Promise<void>(resolve => { started = resolve })
    files.waitForRead(async () => { started(); await gate })
    const first = readFrame(reader, files, 'ok', 0)
    const later = readFrame(reader, files, 'ok', 5)
    const backwards = readFrame(reader, files, 'ok', 2)
    await entered
    expect(files.reads).toHaveLength(1)
    release()
    const sources = await Promise.all([first, later, backwards])
    await assertPixels(sources[0]!, 'ok', 0)
    await assertPixels(sources[1]!, 'ok', 5)
    await assertPixels(sources[2]!, 'ok', 2)
    expect(files.reads).toHaveLength(2)
  })

  for (const [name, corrupt] of [
    ['wrong sequence', (packet: Packet) => ({ ...packet, sequence: 'work' })],
    ['wrong dimensions', (packet: Packet) => ({ ...packet, width: 720 })],
    ['wrong packet offset', (packet: Packet) => ({ ...packet, firstFrame: 6 })],
    ['unknown format', (packet: Packet) => ({ ...packet, format: 'unknown' })],
    ['missing frame', (packet: Packet) => ({ ...packet, frames: [] })],
    ['too many frames', (packet: Packet) => ({ ...packet, frames: [...packet.frames, packet.frames[0]!] })],
    ['wrong frame number', (packet: Packet) => ({ ...packet, frames: [{ ...packet.frames[0]!, frame: 1 }] })],
    ['delta instead of keyframe', (packet: Packet) => ({ ...packet, frames: [{ ...packet.frames[0]!, kind: 'delta' }] })],
    ['truncated compressed data', (packet: Packet) => ({ ...packet, frames: [{ ...packet.frames[0]!, data: packet.frames[0]!.data.slice(0, -12) }] })],
    ['invalid JSON', () => '{'],
  ] as const) {
    test(`rejects ${name} and the next request can recover from a fresh keyframe`, async () => {
      const reader = createBuddyImageReader(), files = fixtureFiles()
      files.rewrite(packet => corrupt(packet) as Packet | string)
      await expect(readFrame(reader, files, 'ok', 0)).rejects.toThrow()
      files.rewrite(undefined)
      await assertPixels(await readFrame(reader, files, 'ok', 1), 'ok', 1)
    })
  }

  test('nonfinite frame requests do not read files or poison subsequent playback', async () => {
    const reader = createBuddyImageReader(), files = fixtureFiles()
    await expect(readFrame(reader, files, 'ok', Number.NaN)).rejects.toThrow('Invalid Buddy frame')
    await expect(readFrame(reader, files, 'ok', Number.POSITIVE_INFINITY)).rejects.toThrow('Invalid Buddy frame')
    expect(files.reads).toHaveLength(0)
    expect(files.markers).toHaveLength(0)
    await assertPixels(await readFrame(reader, files, 'ok', 0), 'ok', 0)
  })
})
